  "source": "def track_max_id(actions):
    max_id = 0
    committed_ids = []
    pending_ids = []
    in_transaction = False
    for action in actions:
        op = action["op"]
        if op == "put":
            id_val = action["id"]
            if in_transaction:
                pending_ids.append(id_val)
            else:
                committed_ids.append(id_val)
            if id_val > max_id:
                max_id = id_val
        elif op == "delete":
            id_val = action["id"]
            if in_transaction:
                if id_val in pending_ids:
                    pending_ids.remove(id_val)
            else:
                if id_val in committed_ids:
                    committed_ids.remove(id_val)
        elif op == "begin":
            in_transaction = True
            pending_ids = list(committed_ids)
        elif op == "commit":
            committed_ids = list(pending_ids)
            in_transaction = False
            pending_ids = []
        elif op == "rollback":
            in_transaction = False
            pending_ids = []
    return max_id

def next_id(max_id):
    return max_id + 1

def investigate(context, acquire):
    max_id = track_max_id(context["actions"])
    return next_id(max_id)",
